/* ============================================================
   STAR TRADER — digital adaptation of Paul Elliott's solo game.
   Trade, world-gen, ship costs & crew use the Cepheus Engine SRD
   (Open Game Content, OGL 1.0a — Samardan Press). The d66 World /
   Port / Jump event tables are from Star Trader (Zozer Games).
   ============================================================ */

const R = (n=6)=>Math.floor(Math.random()*n)+1;          // d-n
const d6 = ()=>R(6);
const d66 = ()=>d6()*10+d6();
const _2d6 = ()=>d6()+d6();
const ehex = v=>{ v=Math.max(0,Math.round(v)); return v<10?String(v):String.fromCharCode(55+v); };
const cr = n=>{ const s=Math.abs(Math.round(n)).toLocaleString('en-US'); return (n<0?'-Cr':'Cr')+s; };

/* ---------- Trade-goods table (Cepheus Engine SRD, OGC) ---------- */
// Cepheus "Trade and Commerce" (Ch.7). Availability is by random D66 roll, NOT
// by trade code; trade codes only drive price. pDM = Purchase DMs (world makes it
// cheap), rDM = Sale DMs (world wants it). Only the LARGEST DM in each column
// applies, and the opposing column subtracts. tons = dice spec rolled at market.
