function goodVariant(id){ const l=GOODNAMES[id]; return l?l[R(l.length)-1]:((ALLGOODS[id]||{}).name||'Cargo'); }
function goodCat(o){ return o.cat||((ALLGOODS[o.id]||{}).name)||''; }   // old-save fallback
function rollTons(spec){            // "2D6*5", "1D6", "4D6*5" ...
  const m=String(spec).match(/^(\d+)D6(?:\*(\d+))?$/i);
  if(!m)return d6();
  const num=+m[1], mult=m[2]?+m[2]:1; let t=0;
  for(let k=0;k<num;k++)t+=d6();
  return t*mult;
}

// Cepheus Modified Price table, keyed by the 2D6 trade-check result (2- .. 16+)
const PRICE={2:[2.00,0.40],3:[1.80,0.50],4:[1.60,0.60],5:[1.40,0.70],6:[1.20,0.80],
 7:[1.10,0.90],8:[1.00,1.00],9:[0.90,1.10],10:[0.80,1.20],11:[0.70,1.40],
 12:[0.60,1.60],13:[0.50,1.80],14:[0.40,2.00],15:[0.30,3.00],16:[0.20,4.00]};
function priceMult(result,sale){ result=Math.max(2,Math.min(16,Math.round(result))); return PRICE[result][sale?1:0]; }
// Cepheus rule: only the single largest DM in a column applies
const maxDM=(dm,codes)=>codes.reduce((m,c)=>Math.max(m,dm[c]||0),0);

